import { useState } from "react";

export default function HoverSwitch() {
  const [hover, setHover] = useState(false);

  return (
    <div
      style={{
        width: "300px",
        height: "200px",
        border: "1px solid black",
        borderRadius: "10px",
        textAlign: "center",
        justifyContent: "center",
        alignItems: "center",
        display: "flex",
        cursor: "pointer"
      }}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
    >

      {hover ? (
        /* هادي الديف الثانية لي كتبان فاش نحط الماوس */
        <div>
          <h2>المحتوى الثاني</h2>
          <p>هذا هو النص الجديد 🎉</p>
        </div>
      ) : (
        /* هادي الديف اللولة */
        <div>
          <h2>المحتوى الأول</h2>
          <p>ديري الماوس باش يتبدل 👀</p>
        </div>
      )}

    </div>
  );
}
